.nav-links{display:flex;align-items:center;gap:1.75rem;list-style:none}
.nav-links a{color:var(--text-muted);font-size:.875rem;font-weight:500;transition:color .15s}
.nav-links a:hover,.nav-links a.active{color:var(--text)}
.nav-right{display:flex;align-items:center;gap:1rem}
.nav-search{display:flex;align-items:center;gap:.5rem;background:var(--bg-card);border:1px solid var(--border);border-radius:6px;padding:.4rem .75rem;font-size:.8rem;color:var(--text-muted);cursor:pointer;transition:border-color .15s}
